-- Built-in decks and cards. Generated by scripts/make-seed.mjs from src/data/; don't edit by hand.
-- Safe to run again: existing rows are updated in place.

insert into public.decks (id, owner_id, name, description, color, topics, position) values
  ('rn', null, 'NCLEX-RN', 'Demo deck of 50 cards across 8 exam areas', '#4f46e5', '{"pharm":{"name":"Pharmacology","color":"#4f46e5"},"physio":{"name":"Physiological Adaptation","color":"#0891b2"},"mgmt":{"name":"Management of Care","color":"#7c3aed"},"safety":{"name":"Safety & Infection Control","color":"#16a34a"},"risk":{"name":"Reduction of Risk","color":"#ea580c"},"health":{"name":"Maternal & Pediatric","color":"#db2777"},"basic":{"name":"Basic Care & Comfort","color":"#ca8a04"},"psych":{"name":"Psychosocial Integrity","color":"#475569"}}'::jsonb, 0),
  ('anat', null, 'Anatomy & Physiology', 'Demo deck of 36 cards, 6 with diagrams', '#0d9488', null, 1),
  ('music', null, 'Music Notes', 'Demo deck: 13 treble-clef notes (middle C to A5) with their sounds, and 10 two-note chords to hear and name', '#ca8a04', null, 2)
on conflict (id) do update set name = excluded.name, description = excluded.description,
  color = excluded.color, topics = excluded.topics, position = excluded.position;

-- NCLEX-RN: 50 cards
insert into public.cards (id, deck_id, owner_id, position, kind, topic, question, answer, explanation, source,
  options, correct, image_front, image_back, sound_front, sound_back) values
  ('p1', 'rn', null, 0, 'recall', 'pharm', 'A client taking digoxin has an apical pulse of 54/min. What should the nurse do?', 'Hold the dose and notify the provider.', 'Hold digoxin when an adult''s apical pulse is below 60/min. Count the apical pulse for a full minute first, and check the latest digoxin and potassium levels: low potassium raises the risk of digoxin toxicity.', null, null, null, null, null, null, null),
  ('ph1', 'rn', null, 1, 'sata', 'physio', 'Which findings suggest hypoglycemia? Select all that apply.', 'Shakiness and sweating, tachycardia, and confusion or irritability.', '“Cool and clammy, need some candy.” Fruity breath and Kussmaul breathing point to DKA. Rule of 15: give 15 g of fast-acting carbohydrate and recheck glucose in 15 minutes.', null, '["Shakiness and sweating","Fruity breath odor","Tachycardia","Confusion or irritability","Kussmaul respirations"]'::jsonb, '[0,2,3]'::jsonb, null, null, null, null),
  ('m1', 'rn', null, 2, 'mc', 'mgmt', 'Which client should the nurse see first?', 'The client with new stridor after a thyroidectomy.', 'Stridor after thyroid surgery signals airway obstruction (swelling, a hematoma, or laryngospasm from low calcium). Airway comes first. The COPD client is at their baseline.', null, '["Post-op day 1, pain 6/10, last pain dose 3 hours ago","Client with COPD, SpO₂ 89% (baseline 88–90%)","Client 6 hours after a thyroidectomy with new high-pitched, noisy breathing","Client with type 2 diabetes, glucose 180 mg/dL before lunch"]'::jsonb, '[2]'::jsonb, null, null, null, null),
  ('s1', 'rn', null, 3, 'sata', 'safety', 'Which conditions require airborne precautions? Select all that apply.', 'Tuberculosis, measles, and varicella.', 'Airborne: negative-pressure room and an N95 respirator. Memory aid “My Chicken Hez TB”: Measles, Chickenpox, disseminated Herpes zoster, TB. Influenza is droplet; C. diff is contact.', null, '["Tuberculosis","Measles (rubeola)","Influenza","Varicella (chickenpox)","C. difficile"]'::jsonb, '[0,1,3]'::jsonb, null, null, null, null),
  ('r1', 'rn', null, 4, 'recall', 'risk', 'A client shows signs of a reaction during a blood transfusion. What is the first action?', 'Stop the transfusion, then keep the IV line open with 0.9% saline through new tubing.', 'Then stay with the client, check vital signs, notify the provider and blood bank, and send the bag and tubing back. Stay with every client for the first 15 minutes of a transfusion, when reactions are most likely.', null, null, null, null, null, null, null),
  ('h1', 'rn', null, 5, 'recall', 'health', 'Late decelerations appear on the fetal monitor. What is the cause, and what does the nurse do?', 'Uteroplacental insufficiency. Stop oxytocin, turn the client to her side, give IV fluids, give oxygen per protocol, and notify the provider.', 'VEAL CHOP: Variable = Cord compression, Early = Head compression, Accelerations = OK, Late = Placental insufficiency.', null, null, null, null, null, null, null),
  ('b1', 'rn', null, 6, 'recall', 'basic', 'How does a stage 1 pressure injury differ from stage 2?', 'Stage 1: intact skin with redness that doesn''t blanch. Stage 2: partial-thickness skin loss with exposed dermis, such as a shallow open wound or a blister.', 'Prevention: reposition at least every 2 hours, keep skin clean and dry, and use pressure-redistributing surfaces.', null, null, null, null, null, null, null),
  ('ps1', 'rn', null, 7, 'recall', 'psych', 'A client with depression suddenly seems calm and is giving away belongings. What should the nurse do?', 'Ask directly about suicide (“Are you thinking of killing yourself?”) and assess for a plan.', 'Sudden calm can mean the client has decided on a plan. Asking directly does not increase risk. Keep the client safe with close observation and tell the team.', null, null, null, null, null, null, null),
  ('p2', 'rn', null, 8, 'recall', 'pharm', 'Furosemide 40 mg IV is due. This morning''s potassium is 3.1 mEq/L. What should the nurse do?', 'Hold the dose and notify the provider.', 'Furosemide is a loop diuretic that wastes potassium. Normal potassium is 3.5–5.0 mEq/L; another dose would push it lower and raise the risk of dysrhythmias.', null, null, null, null, null, null, null),
  ('ph2', 'rn', null, 9, 'recall', 'physio', 'Which ECG change is classic for hyperkalemia?', 'Tall, peaked T waves (later: wide QRS and flattened P waves).', 'Potassium above 5.0 mEq/L can cause dangerous dysrhythmias. Hypokalemia looks the opposite: flat T waves and U waves.', null, null, null, null, null, null, null),
  ('m2', 'rn', null, 10, 'recall', 'mgmt', 'Which tasks can the RN not delegate to assistive personnel (UAP)?', 'Assessment, teaching, evaluation, and care of unstable clients.', 'Memory aid: you can''t delegate what you EAT (Evaluate, Assess, Teach). UAP can take vital signs on stable clients, bathe, feed, help clients walk, and measure intake and output; the RN interprets the results.', null, null, null, null, null, null, null),
  ('s2', 'rn', null, 11, 'recall', 'safety', 'A client has C. difficile. Which precautions, hand hygiene and cleaning are needed?', 'Contact precautions (gown and gloves), handwashing with soap and water, and bleach-based cleaning of surfaces.', 'Alcohol hand rubs don''t kill C. diff spores; the friction of soap-and-water washing removes them.', null, null, null, null, null, null, null),
  ('r2', 'rn', null, 12, 'recall', 'risk', 'After a cardiac catheterization through the femoral artery, what does the nurse monitor?', 'The site for bleeding or hematoma, plus distal pulses, color and warmth of the leg. Keep the leg straight for the ordered bed-rest period.', 'A cool, pale leg or weak pulse may mean a clot; report it right away. New back pain can signal bleeding behind the abdomen (retroperitoneal bleed).', null, null, null, null, null, null, null),
  ('h2', 'rn', null, 13, 'sata', 'health', 'Which findings require the nurse to stop a magnesium sulfate infusion? Select all that apply.', 'Absent reflexes, respiratory rate below 12/min, and urine output below 30 mL/hr.', 'These signal magnesium toxicity (low urine output lets magnesium build up, since the kidneys clear it). Stop the infusion, notify the provider, and have calcium gluconate, the antidote, ready.', null, '["Absent deep tendon reflexes","Respiratory rate below 12/min","Urine output below 30 mL/hr","Blood pressure 150/95","Heart rate 88/min"]'::jsonb, '[0,1,2]'::jsonb, null, null, null, null),
  ('b2', 'rn', null, 14, 'recall', 'basic', 'A client uses a cane. Which hand holds it, and how do they walk?', 'Hold the cane on the strong (unaffected) side, and move the cane forward together with the weak leg.', 'This widens the base of support and takes weight off the weak leg. On stairs: up with the good leg, down with the bad (the cane moves with the bad leg).', null, null, null, null, null, null, null),
  ('ps2', 'rn', null, 15, 'recall', 'psych', 'Which foods must a client taking an MAOI such as phenelzine avoid?', 'Tyramine-rich foods: aged cheeses, cured or smoked meats, soy sauce, tap beer and red wine.', 'Tyramine with an MAOI can cause a hypertensive crisis: severe headache, stiff neck, palpitations.', null, null, null, null, null, null, null),
  ('p3', 'rn', null, 16, 'mc', 'pharm', 'Which medication reverses the effects of warfarin?', 'Vitamin K (phytonadione).', 'Vitamin K reverses warfarin; protamine reverses heparin. Warfarin is monitored with PT/INR (a common target is 2–3); heparin with aPTT.', null, '["Protamine sulfate","Vitamin K (phytonadione)","Naloxone","Acetylcysteine"]'::jsonb, '[1]'::jsonb, null, null, null, null),
  ('ph3', 'rn', null, 17, 'recall', 'physio', 'ABG: pH 7.30, PaCO₂ 52 mmHg, HCO₃⁻ 24 mEq/L. Interpret it.', 'Uncompensated respiratory acidosis.', 'pH below 7.35 means acidosis. PaCO₂ above 45 matches it, so the cause is respiratory. HCO₃⁻ is normal (22–26), so the kidneys haven''t compensated yet.', null, null, null, null, null, null, null),
  ('m3', 'rn', null, 18, 'recall', 'mgmt', 'What does SBAR stand for?', 'Situation, Background, Assessment, Recommendation.', 'SBAR structures handoffs and calls to providers so key facts aren''t missed. Have recent vital signs, labs, medications and the chart ready before calling.', null, null, null, null, null, null, null),
  ('s3', 'rn', null, 19, 'recall', 'safety', 'In what order is PPE put on (donned) and taken off (doffed)?', 'On: gown, mask or respirator, goggles or face shield, gloves. Off: gloves, goggles or face shield, gown, mask or respirator.', 'Gloves come off first because they''re the most contaminated; the mask comes off last, after leaving the room. Clean hands between steps.', null, null, null, null, null, null, null),
  ('r3', 'rn', null, 20, 'recall', 'risk', 'What is the most reliable way to confirm a new NG tube''s placement?', 'X-ray confirmation.', 'Bedside checks support it, such as gastric aspirate with a pH of 5 or less. Listening for air injected through the tube is not reliable.', null, null, null, null, null, null, null),
  ('h3', 'rn', null, 21, 'recall', 'health', 'Postpartum, the fundus is boggy and above the umbilicus. What is the first action?', 'Massage the fundus until it is firm.', 'A soft uterus (atony) is the leading cause of postpartum hemorrhage. Also check for a full bladder, which pushes the uterus up and to one side, and expect an order for oxytocin.', null, null, null, null, null, null, null),
  ('b3', 'rn', null, 22, 'recall', 'basic', 'How should a client receiving a continuous tube feeding be positioned?', 'With the head of the bed raised at least 30–45 degrees.', 'Sitting up lowers the risk of aspiration. Pause the feeding if the client must lie flat.', null, null, null, null, null, null, null),
  ('ps3', 'rn', null, 23, 'recall', 'psych', 'Alcohol withdrawal: when does it start, and when is it most dangerous?', 'It starts about 6–24 hours after the last drink. Seizures can occur in the first 48 hours; delirium tremens usually appears at 48–72 hours.', 'Treatment uses benzodiazepines guided by the CIWA-Ar scale, plus thiamine. Delirium tremens (confusion, hallucinations, fever, unstable vital signs) is a medical emergency.', null, null, null, null, null, null, null),
  ('p4', 'rn', null, 24, 'recall', 'pharm', 'Mixing regular and NPH insulin in one syringe: which is drawn up first?', 'Regular (clear) first, then NPH (cloudy).', '“Clear before cloudy” keeps NPH from contaminating the regular insulin vial. Inject air into the NPH vial, then the regular vial, draw up regular, then NPH.', null, null, null, null, null, null, null),
  ('ph4', 'rn', null, 25, 'recall', 'physio', 'Positive Chvostek''s and Trousseau''s signs point to which imbalance?', 'Hypocalcemia.', 'Low calcium makes nerves more excitable: the face twitches when the cheek is tapped (Chvostek''s), and the hand spasms when a BP cuff is inflated (Trousseau''s). Watch for it after thyroid or parathyroid surgery.', null, null, null, null, null, null, null),
  ('m4', 'rn', null, 26, 'recall', 'mgmt', 'Informed consent: what is the nurse''s role?', 'Witness the signature and confirm the client understands and is signing voluntarily. The provider explains the procedure, risks and alternatives.', 'If the client has questions or seems unsure, hold the signing and notify the provider. Consent needs a competent adult (or legal representative) who hasn''t just been given sedating medication.', null, null, null, null, null, null, null),
  ('s4', 'rn', null, 27, 'recall', 'safety', 'Fire on the unit: what do RACE and PASS stand for?', 'RACE: Rescue, Alarm, Contain, Extinguish. PASS: Pull the pin, Aim at the base, Squeeze, Sweep.', 'Move clients in immediate danger first, then sound the alarm. Closing doors contains smoke and fire.', null, null, null, null, null, null, null),
  ('r4', 'rn', null, 28, 'recall', 'risk', 'Normal adult ranges: sodium, potassium, fasting glucose?', 'Sodium 135–145 mEq/L; potassium 3.5–5.0 mEq/L; fasting glucose 70–100 mg/dL.', 'Ranges vary slightly by lab. If a question gives its own ranges, use those. Potassium has the narrowest safe range and is the most dangerous to get wrong.', null, null, null, null, null, null, null),
  ('h4', 'rn', null, 29, 'recall', 'health', 'When is Rho(D) immune globulin (RhoGAM) given?', 'To an Rh-negative mother at about 28 weeks and within 72 hours after the birth of an Rh-positive baby, and after miscarriage, abortion or abdominal trauma.', 'It stops the mother from forming antibodies that could attack the red blood cells of a future Rh-positive baby.', null, null, null, null, null, null, null),
  ('b4', 'rn', null, 30, 'recall', 'basic', 'What teaching helps prevent dumping syndrome after gastric surgery?', 'Small, frequent meals high in protein and low in simple sugars; drink fluids between meals, not with them; lie down briefly after eating.', 'Food emptying too quickly into the small intestine causes cramping, dizziness, sweating and diarrhea 15–30 minutes after meals.', null, null, null, null, null, null, null),
  ('ps4', 'rn', null, 31, 'mc', 'psych', 'A client says, “Nobody cares whether I live or die.” Which response is most therapeutic?', '“You''re feeling that no one cares about you?”', 'Reflecting the feeling invites the client to say more. “Why” questions sound judgmental, false reassurance dismisses the feeling, and changing the subject shuts the conversation down.', null, '["“Why do you feel that way?”","“That''s not true. Your family visits every day.”","“You''re feeling that no one cares about you?”","“Let''s talk about something more positive.”"]'::jsonb, '[2]'::jsonb, null, null, null, null),
  ('p5', 'rn', null, 32, 'recall', 'pharm', 'A client on lisinopril reports swelling of the lips and tongue. What is the priority?', 'Treat it as angioedema: assess the airway, hold the drug, and notify the provider immediately.', 'Angioedema is a rare but life-threatening ACE-inhibitor reaction that can block the airway. A dry cough is the common, less dangerous side effect.', null, null, null, null, null, null, null),
  ('ph5', 'rn', null, 33, 'recall', 'physio', 'There is continuous bubbling in a chest tube''s water-seal chamber. What does it mean?', 'An air leak. Check the system for loose connections, starting at the client and working down.', 'Gentle rise and fall with breathing (tidaling) is normal. If the tube comes out of the chest, cover the site with a sterile dressing taped on three sides and notify the provider.', null, null, null, null, null, null, null),
  ('m5', 'rn', null, 34, 'recall', 'mgmt', 'After a medication error, where is the incident report filed?', 'On a separate incident (occurrence) report. It is never mentioned in the client''s chart.', 'Chart only the facts: what was given, the client''s condition, who was notified and what was done. The incident report is for quality improvement.', null, null, null, null, null, null, null),
  ('s5', 'rn', null, 35, 'recall', 'safety', 'What are the key safety rules for physical restraints?', 'Use only with a provider''s order and as a last resort. Tie to the bed frame (not the side rails) with a quick-release knot, check circulation and skin often, and release at least every 2 hours.', 'Restraints are never ordered PRN. Try alternatives first (reorientation, a sitter, a bed alarm) and document behavior, alternatives tried and each check.', null, null, null, null, null, null, null),
  ('r5', 'rn', null, 36, 'recall', 'risk', 'What should a client do right before a paracentesis?', 'Empty their bladder.', 'A full bladder can be punctured by the needle. Also record baseline vital signs and weight, and watch blood pressure afterward as fluid shifts.', null, null, null, null, null, null, null),
  ('h5', 'rn', null, 37, 'recall', 'health', 'A child is drooling, has a high fever and sits leaning forward in a tripod position. What must the nurse avoid?', 'Examining or swabbing the throat with a tongue depressor.', 'These are signs of epiglottitis, an airway emergency; touching the throat can trigger complete blockage. Keep the child calm and upright, and have emergency airway equipment ready.', null, null, null, null, null, null, null),
  ('p6', 'rn', null, 38, 'recall', 'pharm', 'What is the usual therapeutic lithium level, and what are early signs of toxicity?', 'About 0.6–1.2 mEq/L. Early toxicity: nausea, vomiting, diarrhea, coarse hand tremor, muscle weakness.', 'Lithium has a narrow therapeutic range. Teach steady sodium and fluid intake (2–3 L a day): dehydration or a low-salt diet raises lithium levels.', null, null, null, null, null, null, null),
  ('ph6', 'rn', null, 39, 'recall', 'physio', 'What are the earliest signs of hypovolemic shock?', 'Rising heart rate, restlessness or anxiety, and cool skin. Low blood pressure is a late sign.', 'The body first compensates by speeding up the heart and narrowing blood vessels. By the time blood pressure drops, a large share of blood volume has been lost.', null, null, null, null, null, null, null),
  ('m6', 'rn', null, 40, 'sata', 'mgmt', 'Which tasks fit an LPN/LVN''s scope when assigned stable clients? Select all that apply.', 'Give scheduled oral meds, reinforce teaching, and collect data.', 'LPNs care for stable clients with predictable outcomes. Initial assessment, care planning and initial teaching stay with the RN. Exact scope varies by state.', null, '["Give scheduled oral medications","Perform an admission assessment","Reinforce discharge teaching the RN started","Collect data such as vital signs and wound appearance","Develop the initial care plan"]'::jsonb, '[0,2,3]'::jsonb, null, null, null, null),
  ('s6', 'rn', null, 41, 'mc', 'safety', 'Which action best prevents falls for a confused older adult?', 'Keep the bed in its lowest position with the call light in reach.', 'A low bed, call light in reach, nonskid socks and scheduled toileting prevent falls. Four raised rails count as a restraint and cause worse injuries when clients climb over them.', null, '["Raise all four side rails","Keep the bed in its lowest position with the call light in reach","Apply a vest restraint at night","Turn off all lights at night"]'::jsonb, '[1]'::jsonb, null, null, null, null),
  ('r6', 'rn', null, 42, 'recall', 'risk', 'What should the nurse watch for in the first 24 hours after a thyroidectomy?', 'Airway problems (stridor, swelling), bleeding (check behind the neck too), and low calcium (tingling around the mouth, muscle cramps).', 'Keep a tracheostomy set and calcium gluconate on hand. New hoarseness may mean laryngeal nerve injury.', null, null, null, null, null, null, null),
  ('p7', 'rn', null, 43, 'recall', 'pharm', 'How should IV vancomycin be infused, and why?', 'Slowly, over at least 60 minutes.', 'A fast infusion can cause vancomycin infusion reaction: flushing and rash on the face, neck and upper body, sometimes low blood pressure. Also monitor trough levels, kidney function and hearing.', null, null, null, null, null, null, null),
  ('ph7', 'rn', null, 44, 'recall', 'physio', 'Suspected ischemic stroke: what must happen before alteplase (tPA) is given?', 'A noncontrast head CT to rule out bleeding, within the treatment window (generally up to 3–4.5 hours from when the client was last known well).', 'A thrombolytic given during a hemorrhagic stroke can be fatal. Record the time the client was last known well.', null, null, null, null, null, null, null),
  ('p8', 'rn', null, 45, 'recall', 'pharm', 'After IV morphine, a client''s respiratory rate is 8/min and hard to rouse. Which drug is given, and what does the nurse watch for afterward?', 'Naloxone. Keep monitoring breathing: the opioid can outlast the naloxone, so repeat doses may be needed.', 'Naloxone works for a shorter time than many opioids. It also reverses pain relief, so expect pain to return and reassess it.', null, null, null, null, null, null, null),
  ('ph8', 'rn', null, 46, 'recall', 'physio', 'What is the Parkland formula for burn fluid resuscitation?', '4 mL × weight (kg) × % TBSA burned of lactated Ringer''s over 24 hours: half in the first 8 hours, the rest over the next 16.', 'The clock starts at the time of the burn, not arrival. Example: 70 kg with 30% TBSA = 8,400 mL, so 4,200 mL in the first 8 hours. Urine output (about 0.5 mL/kg/hr in adults) shows whether fluids are enough.', null, null, null, null, null, null, null),
  ('p9', 'rn', null, 47, 'recall', 'pharm', 'When should a client take levothyroxine?', 'In the morning on an empty stomach, 30–60 minutes before breakfast, with water.', 'Food, calcium, iron and antacids reduce absorption. Palpitations, insomnia or heat intolerance suggest the dose is too high.', null, null, null, null, null, null, null),
  ('ph9', 'rn', null, 48, 'recall', 'physio', 'DKA: what are the key findings, and what comes first in treatment?', 'High glucose, ketones, metabolic acidosis, Kussmaul respirations and fruity breath. IV fluids come first, then an IV regular insulin infusion.', 'Check potassium before and during insulin: insulin moves potassium into cells and can cause severe hypokalemia.', null, null, null, null, null, null, null),
  ('p10', 'rn', null, 49, 'recall', 'pharm', 'A client on metformin is scheduled for a CT scan with iodinated contrast. What does the nurse expect?', 'Metformin is held at the time of the scan and for 48 hours after, and restarted once kidney function is confirmed stable.', 'Contrast can injure the kidneys. If they fail, metformin builds up and can cause lactic acidosis.', null, null, null, null, null, null, null)
on conflict (id) do update set deck_id = excluded.deck_id, position = excluded.position, kind = excluded.kind,
  topic = excluded.topic, question = excluded.question, answer = excluded.answer, explanation = excluded.explanation,
  source = excluded.source, options = excluded.options, correct = excluded.correct,
  image_front = excluded.image_front, image_back = excluded.image_back,
  sound_front = excluded.sound_front, sound_back = excluded.sound_back,
  version = case when (cards.question, cards.answer, cards.explanation, cards.options, cards.correct)
                  is distinct from (excluded.question, excluded.answer, excluded.explanation, excluded.options, excluded.correct)
             then cards.version + 1 else cards.version end;

-- Anatomy & Physiology: 36 cards
insert into public.cards (id, deck_id, owner_id, position, kind, topic, question, answer, explanation, source,
  options, correct, image_front, image_back, sound_front, sound_back) values
  ('an1', 'anat', null, 0, 'recall', null, 'This diagram shows the heart from the front. Which chamber is marked with the question mark?', 'The left ventricle.', 'In a front view the heart''s left side is on your right. The left ventricle has the thickest wall because it pumps blood to the whole body through the aorta. When it fails, blood backs up into the lungs.', null, null, null, 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20width%3D''480''%20height%3D''300''%20viewBox%3D''0%200%20480%20300''%20font-family%3D''Helvetica%2CArial%2Csans-serif''%3E%3Crect%20width%3D''480''%20height%3D''300''%20fill%3D''%23fff''%2F%3E%0A%20%20%3Cg%20stroke-width%3D''3''%20stroke-linejoin%3D''round''%3E%0A%20%20%20%20%3Crect%20x%3D''120''%20y%3D''44''%20width%3D''110''%20height%3D''72''%20rx%3D''18''%20fill%3D''%23dbeafe''%20stroke%3D''%232563eb''%2F%3E%0A%20%20%20%20%3Crect%20x%3D''250''%20y%3D''44''%20width%3D''110''%20height%3D''72''%20rx%3D''18''%20fill%3D''%23fee2e2''%20stroke%3D''%23dc2626''%2F%3E%0A%20%20%20%20%3Cpath%20d%3D''M120%20128%20L230%20128%20L230%20240%20C175%20223%20130%20183%20120%20128%20Z''%20fill%3D''%23dbeafe''%20stroke%3D''%232563eb''%2F%3E%0A%20%20%20%20%3Cpath%20d%3D''M250%20128%20L360%20128%20C358%20193%20315%20243%20250%20263%20Z''%20fill%3D''%23fee2e2''%20stroke%3D''%23dc2626''%2F%3E%0A%20%20%3C%2Fg%3E%3Ccircle%20cx%3D''298''%20cy%3D''178''%20r%3D''16''%20fill%3D''%230f172a''%2F%3E%3Ctext%20x%3D''298''%20y%3D''185''%20text-anchor%3D''middle''%20font-size%3D''19''%20font-weight%3D''700''%20fill%3D''%23fff''%3E%3F%3C%2Ftext%3E%0A%20%20%3Ctext%20x%3D''240''%20y%3D''290''%20text-anchor%3D''middle''%20font-size%3D''12''%20fill%3D''%2364748b''%3EFront%20view%3A%20the%20heart''s%20left%20side%20is%20on%20your%20right%3C%2Ftext%3E%3C%2Fsvg%3E', null, null, null),
