  ('ap1', 'anat', null, 6, 'recall', null, 'What is the basic structural and functional unit of the human body?', 'The cell', 'Cells carry out essential functions such as metabolism and responding to signals.', null, null, null, null, null, null, null),
  ('ap2', 'anat', null, 7, 'recall', null, 'Which plane divides the body into equal right and left halves?', 'The midsagittal plane', 'It passes through the body''s midline.', null, null, null, null, null, null, null),
  ('ap3', 'anat', null, 8, 'recall', null, 'What does proximal mean in anatomy?', 'Closer to the point of attachment', 'The elbow is proximal to the wrist because it is closer to where the arm attaches to the trunk.', null, null, null, null, null, null, null),
  ('ap4', 'anat', null, 9, 'recall', null, 'What is homeostasis?', 'Maintenance of a relatively stable internal environment', 'The body regulates variables such as temperature, blood glucose, and pH as conditions change.', null, null, null, null, null, null, null),
  ('ap5', 'anat', null, 10, 'recall', null, 'What are the four primary tissue types?', 'Epithelial, connective, muscle, and nervous tissue', 'They cover surfaces, support structures, produce movement, and transmit signals, respectively.', null, null, null, null, null, null, null),
  ('ap6', 'anat', null, 11, 'recall', null, 'Which organelle produces most ATP during aerobic respiration?', 'The mitochondrion', 'Its inner membrane contains the machinery for oxidative phosphorylation.', null, null, null, null, null, null, null),
  ('ap7', 'anat', null, 12, 'recall', null, 'Which cells build new bone?', 'Osteoblasts', 'They secrete the organic bone matrix, which later mineralizes.', null, null, null, null, null, null, null),
  ('ap8', 'anat', null, 13, 'recall', null, 'Which cells break down bone?', 'Osteoclasts', 'They resorb bone during remodeling, helping reshape bone and regulate calcium levels.', null, null, null, null, null, null, null),
  ('ap9', 'anat', null, 14, 'recall', null, 'What structure connects skeletal muscle to bone?', 'A tendon', 'Tendons transmit the force of muscle contraction to move bones.', null, null, null, null, null, null, null),
  ('ap10', 'anat', null, 15, 'recall', null, 'What is the basic contractile unit of skeletal muscle?', 'The sarcomere', 'It stretches from one Z disc to the next and shortens as actin and myosin filaments slide past each other.', null, null, null, null, null, null, null),
  ('ap11', 'anat', null, 16, 'recall', null, 'What neurotransmitter triggers skeletal muscle contraction at the neuromuscular junction?', 'Acetylcholine', 'It binds receptors on the muscle fiber, triggering depolarization.', null, null, null, null, null, null, null),
  ('ap12', 'anat', null, 17, 'recall', null, 'What structures make up the central nervous system?', 'The brain and spinal cord', 'They process sensory information and coordinate responses.', null, null, null, null, null, null, null),
  ('ap13', 'anat', null, 18, 'recall', null, 'What is the main function of myelin?', 'To speed up nerve impulse conduction', 'Myelin insulates axons so action potentials can be regenerated at gaps called nodes of Ranvier.', null, null, null, null, null, null, null),
  ('ap14', 'anat', null, 19, 'recall', null, 'What structure normally initiates each heartbeat?', 'The sinoatrial node', 'Located in the right atrium, it generates the electrical impulses that set the heart''s rhythm.', null, null, null, null, null, null, null),
  ('ap15', 'anat', null, 20, 'recall', null, 'Which heart chamber pumps blood into the systemic circulation?', 'The left ventricle', 'It ejects blood into the aorta for delivery to the body''s tissues.', null, null, null, null, null, null, null),
  ('ap16', 'anat', null, 21, 'recall', null, 'Which valve lies between the left atrium and left ventricle?', 'The mitral valve', 'It closes during ventricular contraction to prevent blood from flowing back into the left atrium.', null, null, null, null, null, null, null),
  ('ap17', 'anat', null, 22, 'recall', null, 'What determines whether a blood vessel is an artery or a vein?', 'The direction of blood flow relative to the heart', 'Arteries carry blood away from the heart, and veins carry blood toward it.', null, null, null, null, null, null, null),
  ('ap18', 'anat', null, 23, 'recall', null, 'What protein carries most oxygen in the blood?', 'Hemoglobin', 'Its iron-containing heme groups bind oxygen reversibly inside red blood cells.', null, null, null, null, null, null, null),
  ('ap19', 'anat', null, 24, 'recall', null, 'Where does gas exchange between air and blood occur in the lungs?', 'The alveoli', 'Oxygen and carbon dioxide diffuse across the thin barrier between the alveoli and surrounding capillaries.', null, null, null, null, null, null, null),
  ('ap20', 'anat', null, 25, 'recall', null, 'What happens to the diaphragm during quiet inhalation?', 'It contracts and moves downward', 'This increases thoracic volume and lowers pressure in the lungs, drawing air inward.', null, null, null, null, null, null, null),
  ('ap21', 'anat', null, 26, 'recall', null, 'Where does most nutrient absorption occur?', 'The small intestine', 'Villi and microvilli increase the surface area available for absorption.', null, null, null, null, null, null, null),
  ('ap22', 'anat', null, 27, 'recall', null, 'Which organ produces bile?', 'The liver', 'The gallbladder stores and concentrates bile, which helps emulsify fats in the small intestine.', null, null, null, null, null, null, null),
  ('ap23', 'anat', null, 28, 'recall', null, 'What is the main role of pepsin?', 'To digest proteins in the stomach', 'Pepsin works in acidic conditions and breaks proteins into smaller peptides.', null, null, null, null, null, null, null),
  ('ap24', 'anat', null, 29, 'recall', null, 'What is the functional unit of the kidney?', 'The nephron', 'It filters blood plasma and modifies the filtrate through reabsorption and secretion.', null, null, null, null, null, null, null),
  ('ap25', 'anat', null, 30, 'recall', null, 'Where does blood filtration begin in the nephron?', 'At the glomerulus', 'Pressure drives water and small solutes from glomerular capillaries into Bowman''s capsule.', null, null, null, null, null, null, null),
  ('ap26', 'anat', null, 31, 'recall', null, 'How does antidiuretic hormone affect the kidneys?', 'It increases water reabsorption in the collecting ducts', 'This reduces water loss in urine and makes the urine more concentrated.', null, null, null, null, null, null, null),
  ('ap27', 'anat', null, 32, 'recall', null, 'Which pancreatic cells secrete insulin?', 'Beta cells', 'These cells are located in the pancreatic islets and release insulin when blood glucose rises.', null, null, null, null, null, null, null),
  ('ap28', 'anat', null, 33, 'recall', null, 'What is the main effect of glucagon on blood glucose?', 'It raises blood glucose', 'It signals the liver to break down glycogen and make new glucose.', null, null, null, null, null, null, null),
  ('ap29', 'anat', null, 34, 'recall', null, 'Which immune cells secrete antibodies?', 'Plasma cells', 'They develop from activated B cells and release antibodies that bind specific antigens.', null, null, null, null, null, null, null),
  ('ap30', 'anat', null, 35, 'recall', null, 'Where does fertilization most commonly occur?', 'The ampulla of the uterine tube', 'The ampulla is the widest part of the tube and the usual site where sperm and egg meet.', null, null, null, null, null, null, null)
on conflict (id) do update set deck_id = excluded.deck_id, position = excluded.position, kind = excluded.kind,
  topic = excluded.topic, question = excluded.question, answer = excluded.answer, explanation = excluded.explanation,
  source = excluded.source, options = excluded.options, correct = excluded.correct,
  image_front = excluded.image_front, image_back = excluded.image_back,
  sound_front = excluded.sound_front, sound_back = excluded.sound_back,
  version = case when (cards.question, cards.answer, cards.explanation, cards.options, cards.correct)
                  is distinct from (excluded.question, excluded.answer, excluded.explanation, excluded.options, excluded.correct)
             then cards.version + 1 else cards.version end;

